import functools

def get_game_value(n):
    memo = {}

    def is_terminated(state):
        if not state:
            return True, 0
        s = sum(state)
        if s == 0:
            return True, len(state)
        max_val = max(state)
        if max_val > s - max_val:
            return True, len(state)
        return False, 0

    def solve(state):
        state = tuple(sorted(state))
        if state in memo:
            return memo[state]

        term, val = is_terminated(state)
        if term:
            return val

        # Player A chooses two indices i, j to remove
        # A wants to maximize the result
        best_a = -float('inf')

        # We only need to try unique pairs (x, y)
        unique_pairs = []
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                pair = (state[i], state[j])
                if pair not in unique_pairs:
                    unique_pairs.append(pair)

        for x, y in unique_pairs:
            # Player B chooses to write x+y or |x-y|
            # B wants to minimize the result

            # Option 1: x+y
            next_state1 = list(state)
            # remove one x and one y
            next_state1.remove(x)
            next_state1.remove(y)
            next_state1.append(x + y)
            res1 = solve(tuple(next_state1))

            # Option 2: |x-y|
            next_state2 = list(state)
            next_state2.remove(x)
            next_state2.remove(y)
            next_state2.append(abs(x - y))
            res2 = solve(tuple(next_state2))

            best_b = min(res1, res2)
            best_a = max(best_a, best_b)

        memo[state] = best_a
        return best_a

    return solve(tuple([1] * n))

for n in range(2, 11):
    print(f"N={n}, value={get_game_value(n)}")

